Local Ltac lx_bind_env v ::=
  match goal with
  | |- context [OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.env_setz ?x ?i v] =>
      is_var x;
      let x' := lx_letE in constr_eq x x';
      let e := fresh "lxE" in pose (e := OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.env_setz x i v);
      change (OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.env_setz x i v) with e;
      lazy [x' OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.env_setz OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.pset OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.pad_set
            OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.ezl OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.ewl OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.ebl
            OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.eol OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.ell OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.eml
            OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.elw OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.epr OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.elb0
            OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.ehp OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.ecw OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.elh
            OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.ecur OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.elbl OssFuzzTheorems.Proofs.mbedtls.fuzz_pkcs7.lib.LX.LxDenot.ehr
            Pos.pred Pos.pred_double Pos.succ Pos.eqb N.to_nat Pos.to_nat Pos.iter_op Nat.add Nat.pred] in (value of e)
