Local Ltac gt_lia := lxu_keep_arith; clear_disj; unfold zlow, zswrap in *; first [ lia | (Z.div_mod_to_equations; lia) ].
Local Ltac gt_dec1 K :=
  match type of K with
  | context [Z.ltb ?a ?b] => let E := fresh "E" in
      first [ assert (E : Z.ltb a b = true) by (apply Z.ltb_lt; gt_lia)
            | assert (E : Z.ltb a b = false) by (apply Z.ltb_ge; gt_lia) ];
      rewrite E in K; clear E; cbv beta iota in K
  | context [Z.leb ?a ?b] => let E := fresh "E" in
      first [ assert (E : Z.leb a b = true) by (apply Z.leb_le; gt_lia)
            | assert (E : Z.leb a b = false) by (apply Z.leb_gt; gt_lia) ];
      rewrite E in K; clear E; cbv beta iota in K
  | context [Z.eqb ?a ?b] => let E := fresh "E" in
      first [ assert (E : Z.eqb a b = true) by (apply Z.eqb_eq; gt_lia)
            | assert (E : Z.eqb a b = false) by (apply Z.eqb_neq; gt_lia) ];
      rewrite E in K; clear E; cbv beta iota in K
  end.
Local Ltac gt_bool K := exfalso; repeat gt_dec1 K; first [ discriminate K | (cbn in K; discriminate K) ].
Local Ltac gt_xor :=
  exfalso;
  match goal with H : 0 <= - zlow 64 (Z.lxor ?a ?b) |- _ =>
    let E := fresh "E" in
    assert (E : a = b) by (apply (lx_xor_eq a b); [ gt_lia | gt_lia | exact H ]);
    gt_lia
  end.
Local Ltac gt_chk :=
  rewrite ?Z.lor_m1_l, ?Z.lor_m1_r, ?Z.lor_0_l, ?Z.lor_0_r in *;
  first [ solve [ gt_xor ]
        | match goal with K : @eq bool _ _ |- _ => solve [ gt_bool K ] end ].
Local Ltac gt_bool2prop :=
  repeat match goal with
  | K : (?a <? ?b) = true |- _ => apply Z.ltb_lt in K
  | K : (?a <? ?b) = false |- _ => apply Z.ltb_ge in K
  | K : (?a <=? ?b) = true |- _ => apply Z.leb_le in K
  | K : (?a <=? ?b) = false |- _ => apply Z.leb_gt in K
  | K : (?a =? ?b) = true |- _ => apply Z.eqb_eq in K
  | K : (?a =? ?b) = false |- _ => apply Z.eqb_neq in K
  end.
Local Ltac gt_rng := gt_bool2prop; gt_lia.
Local Ltac gt_mulw :=
  zstep; lx_mkR;
  lazymatch goal with |- context [mkR _ _ _ _ _ _ _ _ _ _ _ _ (Z_to_bv 64 ?y) ?w4 _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _] =>
    let YR := fresh "YR" in let E := fresh "EM" in
    assert (YR : 0 <= y <= 99) by gt_rng;
    assert (E : w4 = Z_to_bv 64 (100 * y))
      by (clear - YR; try unfold v_mulw; rewrite ?Z_to_bv_unsigned; f_equal;
          unfold bv_swrap, bv_wrap; change (bv_half_modulus 32) with (2 ^ 31); change (bv_modulus 32) with (2 ^ 32);
          try change (bv_modulus 64) with (2 ^ 64);
          rewrite ?(Z.mod_small y (2 ^ 64)), ?(Z.mod_small 100 (2 ^ 64)) by lia;
          Z.div_mod_to_equations; lia);
    rewrite E; clear E
  end.

Section Walk.
  Variable R : art_layout.
  #[local] Hint Extern 0 heap_layout => exact (arl_L R) : typeclass_instances.
  Variable HIA : artA asegs R.
  Local Notation AL := (arl_AL R).
  Local Notation L := (arl_L R).
  Hypothesis IMG : asan_img_ok AL.

  Local Instance lxi : LxImg asegs AL := lxA_img AL IMG.   (* [comment removed for export] *)
  Variables (h : HST asegs R HIA) (LB LF : list blk).
